// The analyzers of analyzers.lib as modules that turn a sound into control signals, generated by
// build-faust-library-modules.mjs as the filters (faust-filter-modules.mjs).
//
// - A frequency comes out as a pitch, 0.1 per octave from C4 (log2(f/261.63)/10, from 20 Hz: never infinite):
//   dropped on the Pitch of a VCO (+ add), the VCO plays it; dropped on the Pitch of a filter, the cutoff follows it.
// - A level comes out unipolar, in [0, 1].
// - Response: the time constant of the analysis, in ms on a log scale; a bargraph shows the value measured.
//
// Family: Lib analysis (in FAUST_LIBRARY_FAMILIES), with the Spectral Level of demos.lib.

const PITCH_OF = `// a frequency as a pitch, 0.1 per octave from C4; from 20 Hz, so that a frequency not yet measured (0, at the
// start of a sound, or in silence) gives a low pitch rather than minus infinity (a VCO it drives would be lost)
pitchOf(f) = log(max(20, f) / 261.6256) / log(2) / 10;`;
const RESPONSE = (index, deflt) => `tau = hslider("[${index}]Response[unit:ms][scale:log]", ${deflt}, 1, 1000, 0.1) / 1000;`;

export const ANALYSIS_MODULES = [
    {
        family: "Lib analysis", name: "Pitch Tracker", file: "PitchTracker", source: "an.pitchTracker (analyzers.lib)", inlets: "audio", outlets: "pitch; gate",
        summary: [
            "Pitch tracker: the frequency of the sound, by its zero crossings after an adaptive low pass filter (2nd order), as a pitch (0.1 per octave from C4), and a gate while the sound is above the threshold",
            "Dropped on the Pitch of a VCO and on the Gate of an ADSR, the voice plays what it hears; the gate closes when the sound falls below the threshold or stops (1.5 periods without a zero crossing), and the pitch is held",
            "Response: the time constant (with 20 ms: settled in about 170 ms, within 1.4 cents at 55 Hz, 0.2 cent from 110 Hz); Threshold: the level of the gate (RMS, dB)",
        ],
        body: `process = _ <: (fi.highpass(1, 20) : rising : since), tracked, an.rms_envelope_tau(tau) : voice
with {
    // the frequency of an.pitchTracker (a rate of zero crossings averaged by one pole, which ripples at the
    // frequency of the sound: 100 cents at 220 Hz for 20 ms) smoothed twice more in Hz, before the logarithm:
    // the ripple falls to 0.2 cent at 110 Hz, with no bias
    tracked = an.pitchTracker(2, tau) : fi.lptau(tau) : fi.lptau(tau);
    // the samples since the last rising zero crossing of the sound
    rising(x) = (x > 0) & (x' <= 0);
    since(c) = (+(1) : *(1 - c)) ~ _;
    // the gate: the sound above the threshold, and still crossing zero (a sound that stops leaves the tracker
    // falling for as long as its level takes to fall: the gate closes after 1.5 periods without crossing).
    // The pitch follows while the gate is open; closed, it holds the pitch of two periods before.
    voice(s, hz, level) = attach(select2(gate, held, p), hz : hbargraph("[8]Freq[unit:Hz]", 20, 5000)), gate
    with {
        p = pitchOf(hz);
        period = ma.SR / max(20, hz);
        gate = (level > ba.db2linear(threshold)) & (s < 1.5 * period);
        held = ba.sAndH(gate, p : de.delay(8192, int(2 * period)));
    };
};

${RESPONSE(0, 20)}
threshold = hslider("[1]Threshold[unit:dB]", -40, -80, 0, 0.1);
${PITCH_OF}`,
    },
    {
        family: "Lib analysis", name: "Spectral Centroid", file: "SpectralCentroid", source: "an.spectralCentroid (analyzers.lib)", inlets: "audio", outlets: "pitch",
        summary: [
            "Spectral centroid: the brightness of the sound, the frequency that balances the power above and below it, as a pitch (0.1 per octave from C4)",
            "Dropped on the Pitch of a filter, the cutoff follows the brightness of another sound",
            "Response: the time constant; Nonlinear: a cubic integration, steadier for responses under 5 ms",
        ],
        body: `process = an.spectralCentroid(nonlinear, tau) <: attach(pitchOf, hbargraph("[8]Freq[unit:Hz][scale:log]", 20, 20000));

${RESPONSE(0, 50)}
nonlinear = checkbox("[1]Nonlinear");
${PITCH_OF}`,
    },
    {
        family: "Lib analysis", name: "Zero Crossings", file: "ZeroCrossings", source: "an.zcr (analyzers.lib)", inlets: "audio", outlets: "rate",
        summary: [
            "Zero crossing rate: the part of the samples where the sound changes sign, from 0 to 1; low for a low or pure sound, about 0.5 for a white noise (a sine of f Hz gives 2f/SR)",
            "A measure of the noisiness of a sound, to drop on a setting",
            "Response: the time constant",
        ],
        body: `process = an.zcr(tau) <: attach(_, hbargraph("[8]Rate", 0, 1));

${RESPONSE(0, 50)}`,
    },
    {
        family: "Lib analysis", name: "RMS Level", file: "RMSLevel", source: "an.rms_envelope_tau (analyzers.lib)", inlets: "audio", outlets: "level",
        summary: [
            "RMS level of the sound in dB, as a unipolar signal: 0 at the floor, 1 at 0 dB (a sine of amplitude 1 is at -3 dB)",
            "A level in dB follows the loudness as heard, where the Envelope Follower follows the amplitude",
            "Response: the time constant; Floor: the level that gives 0",
        ],
        body: `process = an.rms_envelope_tau(tau) : ba.linear2db <: attach(_ - bottom : /(-bottom) : max(0) : min(1), hbargraph("[8]Level[unit:dB]", -96, 0));

${RESPONSE(0, 50)}
bottom = hslider("[1]Floor[unit:dB]", -60, -96, -12, 0.1);`,
    },
];
